import{_ as i,a0 as p,w as u,s as a,ao as l,I as s,x as e,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"为防止对开源供应链的攻击，GitHub 在行动 | LCTT x X-CMD","titleTemplate":false,"description":"为防止对开源供应链的攻击，GitHub 在行动 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为防止对开源供应链的攻击，GitHub 在行动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为防止对开源供应链的攻击，GitHub 在行动 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source","title":"为防止对开源供应链的攻击，GitHub 在行动","tag":"202208","desc":""},"relativePath":"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source.md","filePath":"[post].md"}'),d={name:"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source.md"};function T(m,t,b,f,g,S){const o=p("Link");return u(),a("div",null,[t[15]||(t[15]=l('<h1 id="为防止对开源供应链的攻击-github-在行动" tabindex="-1">为防止对开源供应链的攻击，GitHub 在行动 <a class="header-anchor" href="#为防止对开源供应链的攻击-github-在行动" aria-label="Permalink to “为防止对开源供应链的攻击，GitHub 在行动”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/github-cover-1-1068x601.jpg" alt=""></p><p>在 2020 年 SolarWinds 网络间谍活动之后，一系列进一步的软件供应链漏洞凸显了确保软件监管链安全的必要性。在这场间谍活动中，俄罗斯黑客渗透到一个广泛使用的 IT 管理平台，并将受污染的升级程序悄悄带入其中。由于开源项目从根本上来说是分散的，而且经常是临时的活动，因此在这种背景下，这个问题尤其紧迫。GitHub 著名的 npm 注册中心广泛使用的 JavaScript 软件包遭到一系列令人不安的黑客攻击后，该公司前不久公布了一项战略，以提供更好的开源安全保护。</p><p>代码签名平台 Sigstore 将由微软旗下的 GitHub 支持，以用于 npm 软件包。代码签名类似于数字蜡封。为了让开源维护者更加容易地确认他们编写的代码是否与全球范围内人们实际下载的软件包中最终包含的代码相同，跨行业协作促成了该工具的创建。</p><p>GitHub 并不是开源生态系统的唯一组成部分，但 Sigstore 的联合开发者、Chainguard 的首席执行官 Dan Lorenc 指出，它是社区的一个重要枢纽，因为绝大多数项目都在这里存储和共享源代码。然而，当开发人员真正想下载开源软件或工具时，他们通常会通过软件包管理进行。</p><p>通过让包管理器可以使用 Sigstore，开发人员可以在 Sigstore 工具的帮助下，在软件通过供应链时处理加密检查和要求。这增加了产品流通过程中每个阶段的透明度。Lorenc 说，许多人在得知这些完整性检查尚未实施时感到震惊，开源生态系统中相当大的一部分长期以来一直依赖于盲目的信心。拜登政府于 2021 年 5 月发布了一项行政命令，主要涉及软件供应链安全问题。</p><p>Linux 基金会、谷歌、红帽、Purdue Universit 和 Chainguard 都对 Sigstore 的开发做出了贡献。现在有了使用 Sigstore 为 Python 包发行版签名的官方软件，而且开发软件的开源环境 Kubernetes 现在也支持它。</p><p>Sigstore 依靠免费和简单易用来鼓励采用，就像主要行业推动 HTTPS 网络加密一样，这在很大程度上是由非营利组织<ruby>互联网安全研究组<rt>Internet Security Research Group</rt></ruby>的 Let&#39;s Encrypt 等工具实现的。据 GitHub 称，该项目会首先提出 Sigstore 将如何在 npm 中实现的建议，并在开放评论期征求社区人员对该工具的精确部署策略的意见。然而，最终的目标是让这样的代码签名能够被尽可能多的开源项目使用，从而让对供应链的攻击更加困难。</p><p>GitHub 的 Hutchings 说：“我们希望看到这样一个世界，最终所有的软件工件都被签名并链接回源代码，这就是为什么构建像 Sigstore 这样的开放技术栈是如此重要，其他打包存储库也可以采用这种技术。”</p><hr>',10)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/08/github-takes-action-to-prevent-supply-chain-attacks-on-open-source/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/08/github-takes-action-to-prevent-supply-chain-attacks-on-open-source/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:n(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:n(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),r(o,{href:"https://github.com/lzx916"},{default:n(()=>[...t[4]||(t[4]=[e("lzx916",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const x=i(d,[["render",T]]);export{k as __pageData,x as default};
